-- ----- fragment: minion_genesis_36.sql (Genesis 36) -----
-- Chapter: Genesis 36 — THE GENERATIONS OF ESAU, WHO IS EDOM (the dukes of Edom, the Horites, and the kings that reigned in Edom before there reigned any king over the children of Yashar'el). This chapter is LARGELY genealogical — Esau's wives, his sons, the dukes that came of them, the sons of Seir the Horite, and the king-list of Edom. The bare lineage warrants no forced TSK dump. The framework weight is concentrated in three places: (1) the thrice-repeated *Esau is Edom* / *Esau the father of the Edomites* — the bloodline is REAL but runs OUTSIDE the covenant conduit, and Edom becomes the standing adversary-nation; (2) the naming of *Amalek* among Esau's seed (36:12,16) — the first of the nations, the perennial enemy; (3) *these are the kings that reigned in the land of Edom, before there reigned any king over the children of Yashar'el* (36:31) — anticipating Yashar'el's own deferred monarchy promised in *kings shall come out of thee*. Read through VICTIMS-NOT-ENEMIES (Red Line #7): Edom-as-adversary is conduct and covenant-standing, never ethnic hatred; the Malachi/Romans "hated" is covenant-ELECTION language (Jacob have I loved, Esau have I hated = the line of promise vs the line outside it), never a license for contempt.
-- Tag: ge36   Temp view: _s301_ge36_lookup
-- Sort band: base 20875, step 3 -> threads at 20875, 20878, 20881 (3 threads)
-- Source of EVERY row: 'canon','genesis',36,v
--
-- Genesis 36 coverage:
--   ★ v.1, v.8, v.9, v.43 (Now these are the generations of Esau, who is Edom; Thus dwelt Esau in mount Seir: Esau is Edom; the generations of Esau the father of the Edomites in mount Seir; he is Esau the father of the Edomites)
--        NT:     Romans 9:13 (Jacob have I loved, but Esau have I hated) — THREAD 1 (★ election by covenant-purpose, not ethnic spite)
--        Extras: none warranted distinct (Jasher 36:20-25 carries the same Esau genealogy as a flat parallel only, NOT framework-bearing; Jasher 37-38 are the war of the KINGS OF CANAAN against Jacob's sons, a different episode not bound to Genesis 36; Jubilees 38 carries the war of the sons of Esau but its load-bearing verse for this chapter is the king-list at 38:14, placed in THREAD 3)
--        Tanakh: ★ Malachi 1:2-3 (Was not Esau Jacob's brother? yet I loved Jacob, And I hated Esau, and laid his mountains and his heritage waste); Obadiah 1:8 (destroy the wise men out of Edom, and understanding out of the mount of Esau); Obadiah 1:18 (the house of Esau for stubble... there shall not be any remaining of the house of Esau); Numbers 24:18 (And Edom shall be a possession, Seir also shall be a possession for his enemies; and Yashar'el shall do valiantly) — THREAD 1
--   ★ v.12, v.16 (Timna... bare to Eliphaz Amalek: these were the sons of Adah Esau's wife; Duke Amalek... these are the dukes that came of Eliphaz in the land of Edom)
--        NT:     none warranted (the NT carries no Amalek-as-adversary text; the seed-line adversary weave is Tanakh-internal)
--        Extras: none warranted distinct (Jasher 36:27 names the same Amalek of Timna; flat genealogical parallel, not framework-bearing beyond the canon naming)
--        Tanakh: ★ Numbers 24:20 (Amalek was the first of the nations; but his latter end shall be that he perish for ever) — THREAD 2 (the standing adversary born of Esau's seed)
--   ★ v.31 (And these are the kings that reigned in the land of Edom, before there reigned any king over the children of Yashar'el)
--        NT:     none warranted (the deferred-monarchy weave is Tanakh-internal; the kings-shall-come promise is Torah)
--        Extras: ★ Jubilees 38:14 (And these are the kings that reigned in Edom before there reigned any king over the children of Yashar'el until this day in the land of Edom) — THREAD 3 (the restored witness keeps the same formula verbatim)
--        Tanakh: ★ Genesis 17:6 (I will make nations of thee, and kings shall come out of thee); Genesis 35:11 (a nation and a company of nations shall be of thee, and kings shall come out of thy loins) — THREAD 3 (the deferred kingship promised to the covenant line)
--   v.2-7 (Esau's wives of the daughters of Canaan; the removal to mount Seir for their riches)
--        NT: none warranted   Extras: none warranted (Jasher 36:20-22 parallel only)   Tanakh: none warranted (Esau's Canaanite marriages are framed in the ch26-28 packs; the separation-for-riches echoes Genesis 13 Abram/Lot but is not framework-load-bearing here)
--   v.10-19 (the sons of Esau and the dukes that came of them) — bare genealogy
--        NT: none warranted   Extras: none warranted (Jasher 36:23-25 flat parallel)   Tanakh: none warranted
--   v.20-30 (the sons of Seir the Horite and their dukes; that Anah that found the mules/Yemim in the wilderness) — bare genealogy
--        NT: none warranted   Extras: none warranted (Jasher 36:26-37 carries the Anah/Yemim legend expanded, a narrative coda not bound to a framework-type)   Tanakh: none warranted
--   v.32-43 (the king-list of Edom and the closing duke-list) — bare genealogy; the FRAMING verse 36:31 above carries the only weight
--        NT: none warranted   Extras: Jubilees 38:16-24 carries the same king-list as a flat parallel; quoted only at the formula verse 38:14 (THREAD 3), the per-king rows NOT forced   Tanakh: none warranted
--
-- Threads (slug — target libraries):
--   1. genesis-36-esau-is-edom-jacob-have-i-loved-but-esau-have-i-hated — NT (Romans) + Tanakh (Malachi, Obadiah, Numbers) [free] (★ Esau=Edom outside the covenant conduit; election-language, NOT ethnic hatred)
--   2. genesis-36-amalek-the-first-of-the-nations-out-of-esaus-seed — Tanakh (Numbers) [free] (★ the standing adversary born of Esau's line)
--   3. genesis-36-kings-reigned-in-edom-before-any-king-over-yasharel — Tanakh (Genesis 17, Genesis 35) + Extras (Jubilees) [extras] (★ the deferred monarchy of the covenant line)
--
-- Framing notes:
--   ★ ESAU IS EDOM (THREAD 1): the chapter says it three times — *Now these are the generations of Esau, who is Edom* (36:1), *Thus dwelt Esau in mount Seir: Esau is Edom* (36:8), *he is Esau the father of the Edomites* (36:43). The bloodline is real (the twin of Jacob, the firstborn who despised the birthright), but it runs OUTSIDE the covenant conduit. The lens reads Malachi 1:2-3 and Romans 9:13 — *Jacob have I loved, but Esau have I hated* — as covenant-ELECTION language (the line of promise chosen, the line outside it not chosen for the seed), NEVER ethnic spite or a warrant for contempt (Red Line #7, VICTIMS NOT ENEMIES). Obadiah and Numbers 24:18 carry Edom's standing as the adversary-nation under judgment for its conduct against its brother (Obadiah 1:10-12), not for its blood.
--   ★ AMALEK (THREAD 2): *Timna... bare to Eliphaz Amalek* (36:12) — Amalek, the perennial enemy of Yashar'el (the first to attack after the Exodus, the seed Yahuah swore to blot out), is born here of Esau's line. Numbers 24:20 names him *the first of the nations; but his latter end shall be that he perish for ever* — the adversary-seed of Esau set against the seed of promise. Restraint observed: only the one load-bearing Tanakh lateral, no Exodus 17 / Deuteronomy 25 dump.
--   ★ KINGS BEFORE ISRAEL (THREAD 3): *these are the kings that reigned in the land of Edom, before there reigned any king over the children of Yashar'el* (36:31). The narrator marks that Edom had kings BEFORE Yashar'el did — anticipating Yashar'el's own deferred monarchy, the *kings shall come out of thee* (Genesis 17:6) and *kings shall come out of thy loins* (Genesis 35:11) promised to Abraham and to Jacob himself. The restored witness keeps the same formula verbatim: Jubilees 38:14. Weighed lightly per the brief — one Tanakh pair + one clean extras parallel; the per-king rows (36:32-39) left as coverage-only.
--   EXTRAS RESTRAINT: Jasher 36 carries the Esau/Horite genealogy (36:20-37) and the expanded Anah/Yemim legend — genealogical/narrative parallels only, deliberately NOT forced as members. Jasher 37-38 are the WAR OF THE KINGS OF CANAAN against Jacob's sons (a separate episode, not Genesis-36 content). Jubilees 38 carries the war of the sons of Esau and Esau's death; its only Genesis-36-bound verse is the king-list formula at 38:14, used in THREAD 3. Jubilees DOUBLE-WRITTEN 'jubilees','jubilees'.
--   VERSES WITH NO ADD: v.2-7 (Esau's wives, the removal to Seir), v.10-30 (the sons/dukes of Esau and the sons/dukes of Seir the Horite), v.32-43 (the king-list and closing duke-list) — bare genealogy; "none warranted" recorded across all three libraries. The framework weight is held by the framing verses 36:1/8/9/43 (THREAD 1), 36:12/16 (THREAD 2), and 36:31 (THREAD 3).

CREATE TEMP VIEW _s301_ge36_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1: Esau is Edom — Jacob have I loved, but Esau have I hated (the line outside the covenant conduit)
    ('canon','genesis',36,1,'canon','malachi',1,2,'free',
      E'*I have loved you, saith Yahuah (LORD). Yet ye say, Wherein hast thou loved us? Was not Esau Jacob''s brother? saith Yahuah (LORD): yet I loved Jacob* (Malachi 1:2). The chapter opens *Now these are the generations of Esau, who is Edom* (Genesis 36:1) — and centuries on, Yahuah weighs those very twin brothers: *Was not Esau Jacob''s brother?... yet I loved Jacob*. The bloodline of Esau is real, the brother of Jacob, but the covenant-love rested on the chosen line; this is election by promise, the seed-conduit set apart, not a verdict against a people''s blood.'),
    ('canon','genesis',36,1,'canon','malachi',1,3,'free',
      E'*And I hated Esau, and laid his mountains and his heritage waste for the dragons of the wilderness* (Malachi 1:3). The *generations of Esau, who is Edom* (Genesis 36:1) — the dukes, the kings, the mountain-house of Seir — come under this word: *I hated Esau, and laid his mountains and his heritage waste*. Read through the lens, this "hated" is covenant-election language set against "loved Jacob," the line not chosen for the seed; the waste laid on the mountains answers Edom''s conduct as the adversary-nation, never an ethnic contempt.'),
    ('canon','genesis',36,9,'canon','romans',9,13,'free',
      E'*As it is written, Jacob have I loved, but Esau have I hated* (Romans 9:13). Sha''ul (Paul) reaches for the twins to teach election by purpose: he frames it *the children being not yet born, neither having done any good or evil, that the purpose of Elohim (God) according to election might stand* (Romans 9:11). The *generations of Esau the father of the Edomites in mount Seir* (Genesis 36:9) are the line outside that elect purpose — *Esau have I hated* meaning not-chosen for the seed-promise, the conduit running through Jacob; never a license for hatred of the man or his children (Red Line #7).'),
    ('canon','genesis',36,8,'canon','obadiah',1,8,'free',
      E'*Shall I not in that day, saith Yahuah (LORD), even destroy the wise men out of Edom, and understanding out of the mount of Esau?* (Obadiah 1:8). The chapter''s *Thus dwelt Esau in mount Seir: Esau is Edom* (Genesis 36:8) plants the nation in its mountain; Obadiah pronounces the lawsuit upon *the mount of Esau* for its violence against its brother Jacob (Obadiah 1:10). The judgment falls on Edom''s conduct — pride and the gloating over Yahudah''s (Judah''s) calamity — not on the fact of the bloodline named here.'),
    ('canon','genesis',36,8,'canon','obadiah',1,18,'free',
      E'*And the house of Jacob shall be a fire, and the house of Joseph a flame, and the house of Esau for stubble, and they shall kindle in them, and devour them; and there shall not be any remaining of the house of Esau; for Yahuah (LORD) hath spoken it* (Obadiah 1:18). Where Genesis 36:8 establishes *Esau is Edom* in mount Seir, Obadiah sets the two houses of the covenant — *the house of Jacob... the house of Joseph* (Yahudah and Yashar''el, the two sticks) — against *the house of Esau for stubble*. The adversary-nation outside the conduit is consumed; the seed of promise stands.'),
    ('canon','genesis',36,1,'canon','numbers',24,18,'free',
      E'*And Edom shall be a possession, Seir also shall be a possession for his enemies; and Yashar''el (Israel) shall do valiantly* (Numbers 24:18). Balaam''s Star-and-Sceptre oracle weighs the very *Edom* and *Seir* of Esau''s generations (Genesis 36:1, *who is Edom*; 36:8, *in mount Seir*): they *shall be a possession*, while *Yashar''el shall do valiantly*. The line outside the covenant becomes a possession to the line of promise — the seed-war reversal, the chosen seed prevailing over the adversary-house.')
,

    -- THREAD 2: Amalek the first of the nations, out of Esau's seed
    ('canon','genesis',36,12,'canon','numbers',24,20,'free',
      E'*And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever* (Numbers 24:20). Here is where Amalek is born: *Timna was concubine to Eliphaz Esau''s son; and she bare to Eliphaz Amalek* (Genesis 36:12). The perennial enemy of Yashar''el (Israel) — the first to strike after the Exodus, the seed Yahuah swore to blot out — comes of Esau''s line. Balaam names his end: *the first of the nations; but his latter end shall be that he perish for ever* — the adversary-seed of Esau set against the seed of promise.'),
    ('canon','genesis',36,16,'canon','numbers',24,20,'free',
      E'*And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever* (Numbers 24:20). The duke-list crowns him: *Duke Korah, duke Gatam, and duke Amalek: these are the dukes that came of Eliphaz in the land of Edom* (Genesis 36:16). Amalek is no stray name but a DUKE of Edom, a house within Esau''s nation; and Balaam declares that house''s doom — *his latter end shall be that he perish for ever*. The standing adversary born of Esau''s seed is marked for the seed-war''s end.')
,

    -- THREAD 3: Kings reigned in Edom before any king over Yashar'el (the deferred monarchy of the covenant line)
    ('canon','genesis',36,31,'canon','genesis',17,6,'free',
      E'*And I will make thee exceeding fruitful, and I will make nations of thee, and kings shall come out of thee* (Genesis 17:6). The narrator marks *these are the kings that reigned in the land of Edom, before there reigned any king over the children of Yashar''el (Israel)* (Genesis 36:31) — Edom had kings before Yashar''el did. But the covenant carries its own kingship-promise: to Abraham, *kings shall come out of thee*. Edom''s earlier crowns do not eclipse the promise; the deferred monarchy of the covenant line is sworn from the first, awaiting its appointed king.'),
    ('canon','genesis',36,31,'canon','genesis',35,11,'free',
      E'*And Elohim (God) said unto him, I am El Shaddai (God Almighty): be fruitful and multiply; a nation and a company of nations shall be of thee, and kings shall come out of thy loins* (Genesis 35:11). Just before this Esau-genealogy, the same word was renewed to Jacob himself at Bethel — *kings shall come out of thy loins*. So when Genesis 36:31 notes the kings of Edom *before there reigned any king over the children of Yashar''el*, the reader holds the promise already spoken over Jacob: Yashar''el''s monarchy is coming, sworn by El Shaddai, the covenant line''s deferred crown.'),
    ('canon','genesis',36,31,'jubilees','jubilees',38,14,'extras',
      E'*And the sons of Edom have not got quit of the yoke of servitude which the twelve sons of Jacob had imposed on them until this day. And these are the kings that reigned in Edom before there reigned any king over the children of Yashar''el (Israel) until this day in the land of Edom* (Jubilees 38:14). The restored witness keeps the same formula verbatim — *these are the kings that reigned in Edom before there reigned any king over the children of Yashar''el* — matching Genesis 36:31, and frames it under the servitude of Edom to the twelve sons of Jacob: the adversary-house subdued, the covenant line awaiting its own crown.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s301_ge36_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s301_ge36_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-36-esau-is-edom-jacob-have-i-loved-but-esau-have-i-hated',
       E'Esau is Edom — Jacob have I loved, but Esau have I hated',
       E'The chapter says it three times, lest it be missed: *Now these are the generations of Esau, who is Edom* (Genesis 36:1), *Thus dwelt Esau in mount Seir: Esau is Edom* (Genesis 36:8), *he is Esau the father of the Edomites* (Genesis 36:43). The bloodline of Esau is REAL — the twin of Jacob, the firstborn who despised the birthright — but it runs OUTSIDE the covenant conduit. Centuries on, Yahuah (LORD) weighs the very twins: *Was not Esau Jacob''s brother? saith Yahuah (LORD): yet I loved Jacob, And I hated Esau, and laid his mountains and his heritage waste* (Malachi 1:2-3). Sha''ul (Paul) presses the same word and names what it teaches: *the children being not yet born, neither having done any good or evil, that the purpose of Elohim (God) according to election might stand* (Romans 9:11), *As it is written, Jacob have I loved, but Esau have I hated* (Romans 9:13). This is covenant-ELECTION language — the line chosen for the seed-promise and the line not chosen — never ethnic spite, never a warrant for contempt of a man or his children. Edom''s judgment, when it comes, answers conduct: *Shall I not in that day, saith Yahuah (LORD), even destroy the wise men out of Edom, and understanding out of the mount of Esau?* (Obadiah 1:8), for *thy violence against thy brother Jacob* (Obadiah 1:10). And the two houses of the covenant overcome the adversary-house: *the house of Jacob shall be a fire, and the house of Joseph a flame, and the house of Esau for stubble... there shall not be any remaining of the house of Esau; for Yahuah (LORD) hath spoken it* (Obadiah 1:18). Balaam saw it from afar: *And Edom shall be a possession, Seir also shall be a possession for his enemies; and Yashar''el (Israel) shall do valiantly* (Numbers 24:18) — the seed of promise prevailing over the seed outside the conduit, the long enmity of the brothers resolved in favour of the chosen line.',
       sv.verse_id, ev.verse_id, 'free', 20875
  FROM _s301_ge36_lookup sv, _s301_ge36_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=36 AND sv.verse_number=1
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=36 AND ev.verse_number=9
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-36-amalek-the-first-of-the-nations-out-of-esaus-seed',
       E'Amalek the first of the nations — out of Esau''s seed',
       E'Tucked into Esau''s genealogy is the birth of Yashar''el''s (Israel''s) perennial enemy: *And Timna was concubine to Eliphaz Esau''s son; and she bare to Eliphaz Amalek: these were the sons of Adah Esau''s wife* (Genesis 36:12). He is no minor name; the duke-list crowns him: *Duke Korah, duke Gatam, and duke Amalek: these are the dukes that came of Eliphaz in the land of Edom* (Genesis 36:16) — a DUKE of Edom, a house within Esau''s nation. Amalek is the first to strike Yashar''el after the Exodus, the seed Yahuah (LORD) swore to blot out from under heaven. Balaam, looking on him from the heights of Moab, took up his parable: *Amalek was the first of the nations; but his latter end shall be that he perish for ever* (Numbers 24:20). The adversary-seed sprung from Esau''s line — the brother outside the covenant conduit — is set against the seed of promise, and its end is sealed. The enmity of Genesis 3:15 runs on in the houses of men: the seed of the woman and the seed that wars against it, here named with a face — Amalek, of the line of Esau.',
       sv.verse_id, ev.verse_id, 'free', 20878
  FROM _s301_ge36_lookup sv, _s301_ge36_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=36 AND sv.verse_number=12
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=36 AND ev.verse_number=16
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'genesis-36-kings-reigned-in-edom-before-any-king-over-yasharel',
       E'Kings reigned in Edom before any king over Yashar''el — the deferred crown of the covenant line',
       E'The narrator pauses the king-list to mark a thing of weight: *And these are the kings that reigned in the land of Edom, before there reigned any king over the children of Yashar''el (Israel)* (Genesis 36:31). Edom had crowns before Yashar''el did — the line outside the covenant came first to monarchy. But the covenant carries its own kingship-promise, sworn from the beginning. To Abraham: *I will make thee exceeding fruitful, and I will make nations of thee, and kings shall come out of thee* (Genesis 17:6). And to Jacob himself, just before this very Esau-genealogy, renewed at Bethel: *I am El Shaddai (God Almighty): be fruitful and multiply; a nation and a company of nations shall be of thee, and kings shall come out of thy loins* (Genesis 35:11). So Edom''s earlier crowns do not eclipse anything; they only throw the promise into relief — Yashar''el''s monarchy is coming, the deferred crown of the covenant line, and beyond it the King in whom the seed-promise gathers. The restored witness keeps the same formula word-for-word and frames it under Edom''s servitude to the twelve sons of Jacob: *the sons of Edom have not got quit of the yoke of servitude which the twelve sons of Jacob had imposed on them... And these are the kings that reigned in Edom before there reigned any king over the children of Yashar''el (Israel) until this day in the land of Edom* (Jubilees 38:14). The adversary-house may crown its kings early; the covenant line crowns the King who endures.',
       sv.verse_id, ev.verse_id, 'extras', 20881
  FROM _s301_ge36_lookup sv, _s301_ge36_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=36 AND sv.verse_number=31
   AND ev.edition_slug='canon' AND ev.book_slug='genesis' AND ev.chapter_number=36 AND ev.verse_number=31
ON CONFLICT (slug) DO NOTHING;

-- THREAD 1 members
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*Was not Esau Jacob''s brother?... yet I loved Jacob* (Malachi 1:2) — Yahuah weighs the very twins of *the generations of Esau, who is Edom* (36:1); covenant-love on the chosen line.'
  FROM cross_reference_threads t
  JOIN _s301_ge36_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=36 AND sv.verse_number=1
  JOIN _s301_ge36_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='malachi' AND tv.chapter_number=1 AND tv.verse_number=2
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='genesis-36-esau-is-edom-jacob-have-i-loved-but-esau-have-i-hated'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

