INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 3, E'*Jacob have I loved, but Esau have I hated* (Romans 9:13) — Sha''ul reads the twins of *the generations of Esau the father of the Edomites* (36:9) as election by purpose, the seed-conduit through Jacob.'
  FROM cross_reference_threads t
